; --- Begin LAB12/BSCS23065 (1).asm ---
; Question: Lab12 Task 1 - implement a moving text ticker across the top row of the screen.
; Solution: prints a message at a shifting screen column, delays, increments the column, and wraps around.
[org 0x0100]
jmp start

message: db 'Hello World!'
msglen:  dw 12
col:     dw 0

start:
    mov ax, 0xB800
    mov es, ax

ticker:
    ; clear row 0
    mov di, 0
    mov cx, 80
    mov ah, 0x07
    mov al, 0x20
clearrow:
    mov [es:di], ax
    add di, 2
    loop clearrow

    ; calculate chars to print
    mov ax, 80
    sub ax, [col]
    mov bx, [msglen]
    cmp ax, bx
    jge usefull
    mov cx, ax
    jmp startprint
usefull:
    mov cx, bx

startprint:
    mov ax, [col]
    shl ax, 1
    mov di, ax
    mov si, message
    mov ah, 0x07

printloop:
    cmp cx, 0
    je delay
    mov al, [si]
    mov [es:di], ax
    add di, 2
    add si, 1
    dec cx
    jmp printloop

delay:
    mov cx, 0x00FF      ; reduced delay
outer:
    mov bx, 0x00FF
inner:
    dec bx
    jnz inner
    loop outer

    inc word [col]
    mov ax, [col]
    cmp ax, 80
    jl ticker
    mov word [col], 0
    jmp ticker
; --- End LAB12/BSCS23065 (1).asm ---

; --- Begin LAB12/BSCS23065 (2).asm ---
; Question: Lab12 Task 2 - animate four asterisks moving inward and outward from the screen corners.
; Solution: updates corner positions each frame, reverses direction at bounds, and redraws the asterisks.
[org 0x0100]
jmp start

row:  dw 0      ; current row of top-left corner
col:  dw 0      ; current col of top-left corner
dir:  dw 1      ; 1=inward, 0xFFFF=-1=outward

start:
    mov ax, 0xB800
    mov es, ax

mainloop:
    ; check keypress to exit
    mov ah, 0x01
    int 0x16
    jz nodone
    mov ax, 0x4C00
    int 0x21
nodone:

    ; erase all 4 old positions
    call erase

    ; update position
    mov ax, [dir]
    cmp ax, 1
    je movein

    ; moving outward
    dec word [row]
    dec word [col]
    jmp checkbounds

movein:
    inc word [row]
    inc word [col]

checkbounds:
    ; check if reached center (12,12)
    mov ax, [row]
    cmp ax, 12
    je reverse
    ; check if reached corners (0,0)
    cmp ax, 0
    je reverse
    jmp draw

reverse:
    neg word [dir]

draw:
    call drawall

    ; delay
    mov cx, 0x00FF
outer:
    mov bx, 0x00FF
inner:
    dec bx
    jnz inner
    loop outer

    jmp mainloop

; draws asterisk at all 4 corner positions

drawall:
    push ax
    push bx
    push di

    mov ah, 0x0E        ; yellow attribute
    mov al, '*'

    ; top-left: (row, col)
    mov ax, [row]
    mov bx, 80
    mul bx
    add ax, [col]
    shl ax, 1
    mov di, ax
    mov [es:di], ax

    ; top-right: (row, 24-col)
    mov ax, [row]
    mul bx
    mov di, ax
    mov ax, 24
    sub ax, [col]
    add di, ax
    shl di, 1
    mov word [es:di], 0x0E2A

    ; bottom-left: (24-row, col)
    mov ax, 24
    sub ax, [row]
    mul bx
    add ax, [col]
    shl ax, 1
    mov di, ax
    mov word [es:di], 0x0E2A

    ; bottom-right: (24-row, 24-col)
    mov ax, 24
    sub ax, [row]
    mul bx
    mov di, ax
    mov ax, 24
    sub ax, [col]
    add di, ax
    shl di, 1
    mov word [es:di], 0x0E2A

    pop di
    pop bx
    pop ax
    ret

; erases asterisk at all 4 corner positions

erase:
    push ax
    push bx
    push di

    ; top-left
    mov ax, [row]
