; --- Begin LAB12/BSCS23065 (3).asm ---
; Question: Lab12 Task 3 - search the screen buffer for the string "line" and highlight matches.
; Solution: compares a needle string with screen characters and changes the attribute bytes when found.
[org 0x0100]
jmp start

needle:    db 'line'      ; string to search for
nlen:      dw 4           ; length of search string

start:
    mov ax, 0xB800
    mov es, ax
    mov di, 0             ; current screen position (byte offset)
    mov cx, 2000          ; total screen characters

scanloop:
    ; compare needle with screen at current position
    push cx
    push di

    mov si, needle
    mov cx, [nlen]
    mov bx, di            ; save start of match position

matchloop:
    mov al, [es:bx]       ; read ASCII from screen
    mov dl, [si]          ; read char from needle
    cmp al, dl
    jne nomatch           ; mismatch, stop comparing
    add bx, 2             ; next screen char
    add si, 1             ; next needle char
    loop matchloop

    ; full match found — highlight
    pop di                ; restore start position
    push di
    mov cx, [nlen]
    mov bx, di
highlightloop:
    mov byte [es:bx+1], 0x4E  ; red background yellow text
    add bx, 2
    loop highlightloop

nomatch:
    pop di
    pop cx
    add di, 2             ; move to next screen position
    loop scanloop

    mov ax, 0x4C00
    int 0x21
; --- End LAB12/BSCS23065 (3).asm ---

; --- Begin LAB12/BSCS23065 (4).asm ---
; Question: Lab12 Task 4 - copy a block of screen text to a buffer, clear the screen, and center it.
; Solution: saves source rows to a buffer, clears video memory, then writes the buffered block centered on screen.
[org 0x0100]
jmp start

src_top:  dw 1
src_bot:  dw 3
dst_top:  dw 0

start:
    mov ax, 0xB800
    mov es, ax

    ; height = src_bot - src_top + 1 = 3
    mov ax, [src_bot]
    sub ax, [src_top]
    inc ax
    mov bx, ax              ; BX = 3

    ; dst_top = (25 - 3) / 2 = 11
    mov ax, 25
    sub ax, bx
    shr ax, 1
    mov [dst_top], ax       ; dst_top = 11

    ; step 1 - save source into buffer
    mov ax, [src_top]
    mov cx, 160
    mul cx
    mov si, ax              ; SI = row 1 offset = 160

    mov di, buffer
    mov ax, bx
    mov cx, 80
    mul cx
    mov cx, ax              ; CX = 3*80 = 240 words

saveloop:
    mov ax, [es:si]
    mov [di], ax
    add si, 2
    add di, 2
    loop saveloop

    ; step 2 - clear screen
    mov di, 0
    mov cx, 2000
    mov ah, 0x07
    mov al, 0x20
clrloop:
    mov [es:di], ax
    add di, 2
    loop clrloop

    ; step 3 - write buffer to center (row 11)
    mov ax, [dst_top]
    mov cx, 160
    mul cx
    mov di, ax              ; DI = row 11 offset = 1760

    mov si, buffer
    mov cx, 240             ; 3 rows * 80 chars

writeloop:
    mov ax, [si]
    mov [es:di], ax
    add si, 2
    add di, 2
    loop writeloop

    mov ax, 0x4C00
    int 0x21

buffer: times 480 db 0
; --- End LAB12/BSCS23065 (4).asm ---

