; --- Begin Lab13/23065 (2).asm ---
; Question: Lab13 Task 2 - animate two bouncing asterisks moving across the screen borders.
; Solution: updates positions, reverses direction at edges, erases previous positions, and redraws them.
[org 0x0100]
jmp start

; asterisk 1
r1:     dw 0
c1:     dw 0
rd1:    dw 1        ; row dir down
cd1:    dw 1        ; col dir right

; asterisk 2
r2:     dw 0
c2:     dw 79
rd2:    dw 1        ; row dir down
cd2:    dw 0xFFFF   ; col dir left (-1)

start:
    mov ax, 0xB800
    mov es, ax

    ; clear screen
    xor di, di
    mov ax, 0x0720
    mov cx, 2000
    rep stosw

mainloop:
    ; check keypress to exit
    mov ah, 0x01
    int 0x16
    jz nodone
    mov ax, 0x4C00
    int 0x21
nodone:

    ; erase asterisk 1
    mov ax, [r1]
    mov bx, 80
    mul bx
    add ax, [c1]
    shl ax, 1
    mov di, ax
    mov word [es:di], 0x0720

    ; erase asterisk 2
    mov ax, [r2]
    mov bx, 80
    mul bx
    add ax, [c2]
    shl ax, 1
    mov di, ax
    mov word [es:di], 0x0720

    ; update asterisk 1 position
    mov ax, [r1]
    add ax, [rd1]
    mov [r1], ax
    mov ax, [c1]
    add ax, [cd1]
    mov [c1], ax

    ; bounce asterisk 1
    mov ax, [r1]
    cmp ax, 24
    jl chkr1top
    mov word [rd1], 0xFFFF
chkr1top:
    cmp ax, 0
    jg chkc1right
    mov word [rd1], 1
chkc1right:
    mov ax, [c1]
    cmp ax, 79
    jl chkc1left
    mov word [cd1], 0xFFFF
chkc1left:
    cmp ax, 0
    jg ast2update
    mov word [cd1], 1

    ; update asterisk 2 position
ast2update:
    mov ax, [r2]
    add ax, [rd2]
    mov [r2], ax
    mov ax, [c2]
    add ax, [cd2]
    mov [c2], ax

    ; bounce asterisk 2
    mov ax, [r2]
    cmp ax, 24
    jl chkr2top
    mov word [rd2], 0xFFFF
chkr2top:
    cmp ax, 0
    jg chkc2right
    mov word [rd2], 1
chkc2right:
    mov ax, [c2]
    cmp ax, 79
    jl chkc2left
    mov word [cd2], 0xFFFF
chkc2left:
    cmp ax, 0
    jg drawboth
    mov word [cd2], 1

drawboth:
    ; draw asterisk 1
    mov ax, [r1]
    mov bx, 80
    mul bx
    add ax, [c1]
    shl ax, 1
    mov di, ax
    mov word [es:di], 0x0E2A

    ; draw asterisk 2
    mov ax, [r2]
    mov bx, 80
    mul bx
    add ax, [c2]
    shl ax, 1
    mov di, ax
    mov word [es:di], 0x0C2A

    ; delay
    mov cx, 0x00FF
outer:
    mov bx, 0x00FF
inner:
    dec bx
    jnz inner
    loop outer

    jmp mainloop
; --- End Lab13/23065 (2).asm ---

; --- Begin Lab13/23065 (3).asm ---
; Question: Lab13 Task 3 - count vowels in a string and display the count in hexadecimal.
; Solution: scans the string for vowel characters, increments a counter, converts the count to hex, and prints it.
[org 0x0100]
jmp start

mystring: db 'Hello saifi This Is Assembly'
strlen:   dw 36
vowelcount: dw 0

start:
    mov ax, cs
    mov ds, ax

    mov ax, 0xB800
    mov es, ax

    ; clear screen
    xor di, di
    mov ax, 0x0720
    mov cx, 2000
    rep stosw

    ; count vowels
    mov si, mystring
    mov cx, [strlen]
    mov word [vowelcount], 0

nextchar:
    lodsb               ; AL = next char, SI++
    cmp al, 'a'
    je isvowel
    cmp al, 'e'
    je isvowel
    cmp al, 'i'
    je isvowel
    cmp al, 'o'
    je isvowel
    cmp al, 'u'
    je isvowel
    cmp al, 'A'
    je isvowel
    cmp al, 'E'
    je isvowel
    cmp al, 'I'
    je isvowel
    cmp al, 'O'
    je isvowel
    cmp al, 'U'
    je isvowel
    jmp notvowel

isvowel:
    inc word [vowelcount]

notvowel:
    loop nextchar

    ; print vowel count in hex at last row (offset 3840)
    mov di, 3840
    mov ax, [vowelcount]
    mov bx, 16
    mov cx, 0

hexloop:
    mov dx, 0
    div bx
    cmp dl, 9
    jle isnum
    add dl, 0x37
    jmp pushdigit
isnum:
    add dl, 0x30
pushdigit:
    push dx
    inc cx
    cmp ax, 0
    jnz hexloop

printloop:
    pop dx
    mov dh, 0x0E
    mov [es:di], dx
    add di, 2
    loop printloop

    mov ax, 0x4C00
    int 0x21
; --- End Lab13/23065 (3).asm ---

; --- Begin Lab13/23065 (4).asm ---
; Question: Lab13 Task 4 - draw a moving asterisk around the screen perimeter in a square path.
; Solution: uses phase state to move right, down, left, and up, drawing the asterisk step by step.
[org 0x0100]
jmp start

row:    dw 0
col:    dw 0
phase:  dw 0        ; 0=top 1=right 2=bottom 3=left

start:
    mov ax, 0xB800
    mov es, ax

    xor di, di
    mov ax, 0x0720
    mov cx, 2000
    rep stosw

mainloop:
    ; check keypress
    mov ah, 0x01
    int 0x16
    jz nokey
    mov ax, 0x4C00
    int 0x21
nokey:

    ; erase old position
    mov ax, [row]
    mov bx, 80
    mul bx
    add ax, [col]
    shl ax, 1
    mov di, ax
    mov word [es:di], 0x0720

    ; update position based on phase
    mov ax, [phase]
    cmp ax, 0
    je dotop
    cmp ax, 1
    je doright
    cmp ax, 2
    je dobottom
    jmp doleft

dotop:
    inc word [col]
    mov ax, [col]
    cmp ax, 79
    jl draw
    mov word [phase], 1
    jmp draw

doright:
    inc word [row]
    mov ax, [row]
    cmp ax, 24
    jl draw
    mov word [phase], 2
    jmp draw

dobottom:
    dec word [col]
    mov ax, [col]
    cmp ax, 0
    jg draw
    mov word [phase], 3
    jmp draw

doleft:
    dec word [row]
    mov ax, [row]
    cmp ax, 0
    jg draw
    mov word [phase], 0
    jmp draw

draw:
    ; draw asterisk at new position
    mov ax, [row]
    mov bx, 80
    mul bx
    add ax, [col]
    shl ax, 1
    mov di, ax
    mov word [es:di], 0x0B2A

    ; delay
    mov cx, 0x00FF
outer:
    mov bx, 0x00FF
inner:
    dec bx
    jnz inner
    loop outer

    jmp mainloop
; --- End Lab13/23065 (4).asm ---

